insert into public.courses (id, slug, title, description, published) values
  ('627837c6-f8a7-5a58-8da2-afcb16683b36', 'ai-web-developer', 'AI Web Developer', 'From your first Claude prompt to a complete production-ready website.', true)
insert into public.levels (id, course_id, slug, title, description, position, published) values
  ('0117796f-d1ee-5e5a-8132-f58c5592b527', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'think-like-a-builder', 'Think Like a Builder', 'Understand how websites are actually put together, and what changes when an AI writes the code.', 1, true),
  ('dc1a60ee-68f1-5dfe-908c-65b35b975f35', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'mastering-claude', 'Mastering Claude', 'Learn to direct a model instead of hoping for a good answer: context, constraints, design direction, existing code.', 2, true),
  ('4b9dbcc2-d326-51f9-913a-3d45622166bd', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'your-first-website', 'Your First Website', 'Take one idea from an empty folder to a responsive page that works on a phone.', 3, true),
  ('d6c8b7b8-d769-54cf-9cf3-f6a1f8f59db0', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'prompt-engineering-for-developers', 'Prompt Engineering for Developers', 'The nine prompt shapes that do the work, and how to chain them into a session that goes somewhere.', 4, true),
  ('0a9dece4-ba97-5f92-8552-476a68ade471', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'build-like-a-professional', 'Build Like a Professional', 'The difference between a page that works and a page a studio would ship.', 5, true),
  ('b879945d-7b93-55d1-b6e5-878439a89c29', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'debugging-with-claude', 'Debugging with Claude', 'Read the failure, describe it precisely, and verify the fix instead of trusting it.', 6, true),
  ('6eb9b656-1b10-570e-9111-dd18aab1a90d', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'advanced-web-building', 'Advanced Web Building', 'Layout, state, data and architecture — the parts a generated page usually gets wrong.', 7, true),
  ('0e3df840-08ac-5805-9967-87d6016c8ea8', '627837c6-f8a7-5a58-8da2-afcb16683b36', 'ship-it', 'Ship It', 'Test it, tighten it, put it online, and check the things that only break in public.', 8, true)
insert into public.lessons (id, level_id, slug, title, description, content, position, published, estimated_minutes, video_url, video_duration) values
  ('097d8418-6285-5066-bc1a-ec7576676130', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'what-is-ai-assisted-development', 'What is AI-assisted development?', 'The job did not disappear. It moved.', '[{"t": "h", "text": "The work moved. It did not vanish."}, {"t": "p", "text": "There is a story going around that AI writes the website now and you just ask nicely. It is wrong in a specific and useful way. A model can produce a page faster than any human can type one. What it cannot do is decide whether that page is the right page — and that decision is most of the job."}, {"t": "p", "text": "So the work moves. Away from remembering syntax, towards **deciding, directing, reading and judging**. You will still open a code editor. You will spend less time typing into it and far more time looking at what came back and asking whether it deserves to ship."}, {"t": "figure", "kind": "shift", "caption": "What a developer spends time on, before and after"}, {"t": "h", "text": "What actually changes"}, {"t": "p", "text": "Three things get dramatically cheaper: the first draft, the boring parts, and the explanation. A layout that used to cost an afternoon costs a minute. A regular expression you would have looked up costs nothing. An unfamiliar piece of code can be explained back to you line by line."}, {"t": "p", "text": "Three things get no cheaper at all: knowing what to build, knowing whether it is good, and being responsible for it when it breaks. Those are the parts a client is actually paying for, and they are the parts this course is about."}, {"t": "callout", "kind": "note", "title": "The uncomfortable version", "text": "If your only skill is producing code that works, that skill is now commodity. If you can decide what should exist, direct a model towards it, and tell the difference between good and merely working — you have more leverage than you have ever had."}, {"t": "h", "text": "Generation is not the hard part"}, {"t": "p", "text": "Watch someone new to this and you will see the same pattern. They ask for a website. They get one. It looks plausible. They ask for a change. They get a different plausible thing, and something that worked before quietly stops working. Twenty minutes later they have a folder of code nobody understands, including them."}, {"t": "p", "text": "Nothing went wrong technically. What went wrong is that no one was steering. Every prompt was a fresh wish rather than a step in a build."}, {"t": "demo", "kind": "context-compare", "title": "The same request, two ways"}, {"t": "h", "text": "The mental model that works"}, {"t": "p", "text": "Treat the model as an extremely fast, extremely well-read colleague who has never seen your project, has no opinion about your client, and will do exactly what you asked rather than what you meant. That colleague is genuinely valuable. They are not a replacement for knowing what you want."}, {"t": "list", "items": ["You decide what to build. The model proposes how.", "You give context. Without it, you get the average of everything it has ever read.", "You read the output. Not to admire it — to judge it.", "You own the result. The model is not on the invoice."]}, {"t": "prompt", "n": "01", "title": "A first prompt that earns its place", "body": "I am learning AI-assisted web development. Explain, in plain language and in under 200 words, the difference between what a browser downloads and what a server does. Assume I have never written code. Use one concrete example: someone opening a bakery''s website on their phone.", "why": {"context": "It states who you are and what you already know, so the answer is pitched at you rather than at nobody.", "constraints": "Under 200 words, plain language, one example. Each one rules out a kind of answer you did not want.", "output": "An explanation, not code — which is the right output for the question being asked.", "iteration": "If a sentence loses you, quote it back and ask for that sentence alone to be re-explained. Do not restart."}}, {"t": "task", "title": "Try it before the next lesson", "steps": ["Open Claude and run the prompt above, unchanged.", "Read the answer and find the one sentence you are least sure about.", "Quote that sentence back and ask for it to be explained differently.", "Notice how much better the second answer is — and that the improvement came from you, not the model."], "done": "You have had a conversation rather than made a request. That distinction is the whole course."}, {"t": "quiz", "q": "What gets cheaper with AI assistance, and what does not?", "type": "single", "options": ["Everything gets cheaper at roughly the same rate", "Producing code gets much cheaper; deciding what to build and judging quality do not", "Only boilerplate gets cheaper; real code is unaffected", "Nothing changes, the tools are just faster autocomplete"], "correct": [1], "why": "First drafts and boilerplate collapse in cost. Judgement, taste and responsibility do not move at all — which is why they are where your value now sits."}, {"t": "summary", "points": ["The work moved from typing to deciding, directing, reading and judging.", "Generation is the cheap half. Steering is the half that is worth money.", "Treat the model as a fast colleague with no context, not as an oracle.", "You own the output, so you have to be able to read it."]}]'::jsonb, 1, true, 9, null, null),
  ('734623b4-31fc-5874-8621-dd1b7dcd5497', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'how-websites-actually-work', 'How websites actually work', 'One request, three files, and a machine that does exactly what it is told.', '[{"t": "h", "text": "A website is a conversation between two machines."}, {"t": "p", "text": "Someone types an address. Their browser sends a request across the network. A server somewhere answers with a file. The browser reads that file, discovers it needs a few more, asks for those too, and then draws the result on screen. That is the entire mechanism. Everything else is detail."}, {"t": "figure", "kind": "request", "caption": "What happens between typing an address and seeing a page"}, {"t": "h", "text": "The browser is not clever, and that is good news"}, {"t": "p", "text": "A browser does not interpret your intentions. It reads instructions and follows them precisely. If your page looks wrong, the browser is not confused — it is doing exactly what your code says. This is the single most useful belief you can hold while debugging: **the machine is not being difficult, your instructions are.**"}, {"t": "p", "text": "Watch the order it works in. First it reads the HTML and builds a tree of elements. Then it applies the CSS to decide how each element looks and where it sits. Then it runs the JavaScript, which can change either of those. Then it paints. When something appears and then jumps, you have usually watched that sequence happen out of order."}, {"t": "code", "lang": "html", "filename": "index.html", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <title>Vlaam Bakery</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n  </head>\n  <body>\n    <h1>Bread, daily, from six.</h1>\n    <script src=\"script.js\"></script>\n  </body>\n</html>"}, {"t": "p", "text": "That file is a complete website. It is not a good one, but nothing is missing. The `<link>` tells the browser to go and fetch a second file. The `<script>` tells it to fetch a third. Three requests, one page."}, {"t": "callout", "kind": "tip", "title": "Open the Network panel once", "text": "Right-click any page, choose Inspect, open the Network tab and reload. Every row is one request. This is not an advanced tool — it is the honest picture of what a website is, and it takes ten seconds to look at."}, {"t": "h", "text": "Why this matters for prompting"}, {"t": "p", "text": "When you know a page is files fetched over a network, a lot of vague requests turn into precise ones. ''Make it load faster'' becomes ''reduce the number of requests and the size of the largest one''. ''It flashes when it loads'' becomes ''the CSS arrives after the first paint''. You cannot ask for what you cannot name."}, {"t": "figure", "kind": "layers", "caption": "The three layers, and what each one is responsible for"}, {"t": "prompt", "n": "02", "title": "Read your own page back", "body": "Here is my index.html:\n\n{PASTE FILE}\n\nWalk me through exactly what the browser does with this file, in order, from the moment it arrives. Say which additional files it will request and when. Point out anything that would delay the first paint. Do not suggest improvements yet — I want to understand the sequence first.", "why": {"context": "Your actual file, not a generic example, so the explanation is about your page.", "constraints": "''In order'' forces a sequence rather than a summary. ''No improvements yet'' keeps the answer explanatory.", "output": "A walkthrough you can check against the Network panel.", "iteration": "Once you understand the sequence, ask for the single change that would most improve first paint."}}, {"t": "task", "title": "Build the smallest possible website", "steps": ["Make a folder called `first-site`.", "Create `index.html` and paste the example above into it.", "Double-click the file. It opens in your browser. That is a website.", "Open the Network panel and reload. Count the failed requests — styles.css and script.js do not exist yet.", "Create both files, empty, and reload. The failures disappear."], "done": "You have seen a page request files, fail to find them, and then find them. Most confusing bugs are a version of this."}, {"t": "quiz", "q": "A page renders, then a moment later the fonts and colours snap into place. What does that tell you?", "type": "single", "options": ["The server is slow", "The browser painted before the stylesheet had arrived and been applied", "The JavaScript failed", "The images are too large"], "correct": [1], "why": "The browser paints what it has. If the stylesheet arrives after the first paint, you see the unstyled version first. Knowing the sequence turns a mysterious flicker into a specific, fixable cause."}, {"t": "summary", "points": ["A website is files requested over a network and drawn by a browser.", "The browser reads HTML, applies CSS, runs JavaScript, then paints — in that order.", "The machine follows instructions exactly; wrong output means wrong instructions.", "Naming the mechanism is what lets you ask a precise question about it."]}]'::jsonb, 2, true, 11, null, null),
  ('a044bdc0-1547-528e-8935-8eb24968a3e7', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'frontend-vs-backend', 'Frontend vs backend', 'Not a difficulty ranking. A question of whose computer it runs on.', '[{"t": "h", "text": "Whose computer is it running on?"}, {"t": "p", "text": "That is the whole distinction. Front end runs on the visitor''s device, inside their browser. Back end runs on a machine you control. People treat this as a seniority ladder — it is not. It is a boundary, and the boundary has consequences you need to feel in your bones."}, {"t": "figure", "kind": "split", "caption": "The boundary, and what it means for trust"}, {"t": "h", "text": "The consequence that matters"}, {"t": "p", "text": "Anything running on the visitor''s device is under the visitor''s control. They can read it, pause it, change it and lie to it. This is not a flaw to be patched — it is what a browser is. A person can open the developer tools right now and edit any page they are looking at."}, {"t": "p", "text": "So: a check that lives in the browser is a convenience, not a rule. Hiding an admin button stops nobody. Validating a form in the browser makes it pleasant to fill in; it does not make the data safe. **Every rule that actually matters has to be enforced on the server.**"}, {"t": "callout", "kind": "warning", "title": "The mistake that ends careers early", "text": "Never put a secret in code the browser downloads. Not an API key, not a password, not a database credential. If the browser can read it, so can everyone who visits your site — including the person who is looking for exactly that."}, {"t": "p", "text": "This course''s own platform is a working example. The interface hides the admin section from a student, because showing it would be confusing. But the actual protection is a rule on the database that refuses to return other people''s data to a student''s session, no matter what the browser asks for. The hidden button is manners. The database rule is security."}, {"t": "h", "text": "What lives where"}, {"t": "list", "items": ["**Front end** — layout, typography, interactions, animation, form usability, anything the visitor sees or touches.", "**Back end** — accounts and passwords, permissions, saved data, payments, anything that must be true regardless of what the browser claims.", "**Both, deliberately** — validation. Check in the browser so the form is pleasant. Check again on the server because that is the check that counts."]}, {"t": "demo", "kind": "trust-boundary", "title": "Which side does this belong on?"}, {"t": "prompt", "n": "03", "title": "Ask where a rule belongs", "body": "I am building {FEATURE}. List every rule that has to be true for it to work correctly.\n\nFor each rule, tell me whether it must be enforced on the server, whether it should also be checked in the browser for usability, and what an attacker could do if it were only checked in the browser.\n\nBe blunt about the consequences. I would rather be uncomfortable now.", "why": {"context": "Naming the feature lets the model infer rules you have not thought of.", "constraints": "Forcing a server/browser answer per rule prevents a vague ''validate both sides'' response.", "output": "A table of decisions plus the consequence of getting each one wrong.", "iteration": "Take the highest-consequence rule and ask how to enforce it on the server in your stack."}}, {"t": "task", "title": "Break a page on purpose", "steps": ["Open any site with a form that has a disabled submit button.", "Right-click the button and choose Inspect.", "Delete the `disabled` attribute in the elements panel.", "The button is now clickable. You changed their page — on your machine only.", "Sit with what that means for every check written in the browser."], "done": "You have felt the trust boundary rather than read about it. That feeling is what stops you writing an insecure feature later."}, {"t": "quiz", "q": "Your app hides the ''Delete user'' button unless the logged-in account is an admin. Is that sufficient?", "type": "single", "options": ["Yes — a student cannot see the button, so they cannot use it", "No — the browser can be edited, so the server must refuse the request as well", "Yes, provided the button is removed rather than hidden with CSS", "It depends on whether the site uses HTTPS"], "correct": [1], "why": "Hiding a control is user experience. The delete endpoint itself has to check who is asking and refuse anyone who is not an admin — that check is the security. HTTPS protects the message in transit; it says nothing about who is allowed to send it."}, {"t": "summary", "points": ["Front end runs on their computer, back end on yours. That is the whole definition.", "Anything the browser receives, the visitor can read and change.", "Browser checks are for usability. Server checks are for correctness and safety.", "Never put a secret in front-end code."]}]'::jsonb, 3, true, 10, null, null),
  ('8c66b0a1-6fa3-53db-8fde-4f411b2e0507', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'html-css-javascript', 'HTML, CSS & JavaScript', 'Structure, appearance and behaviour — and why keeping them separate makes AI output far easier to fix.', '[{"t": "h", "text": "Three languages, three jobs."}, {"t": "p", "text": "HTML says what things *are*. CSS says how they *look*. JavaScript says how they *behave*. That separation is not academic tidiness — it is what lets you change one thing without breaking the other two, and it is the first thing to check when generated code becomes hard to work with."}, {"t": "figure", "kind": "layers", "caption": "Same content, three layers of responsibility"}, {"t": "h", "text": "HTML: meaning, not appearance"}, {"t": "p", "text": "Choosing `<button>` instead of `<div>` is not pedantry. A real button is focusable by keyboard, announces itself to a screen reader, and responds to the space bar — for free, because you used the right element. A `<div>` styled to look like a button has none of that until you rebuild it by hand, badly."}, {"t": "code", "lang": "html", "filename": "index.html", "code": "<!-- meaning is visible in the markup -->\n<article class=\"card\">\n  <h2>Sourdough</h2>\n  <p>Twenty-four hour ferment. Out at six.</p>\n  <button type=\"button\">Reserve a loaf</button>\n</article>"}, {"t": "p", "text": "Read that without any CSS and you still know what it is. That is the test. If you have to look at the stylesheet to work out what a piece of markup means, the markup is wrong."}, {"t": "h", "text": "CSS: a system, not a pile of rules"}, {"t": "p", "text": "Most generated CSS works and is still bad, for one reason: it repeats itself. A colour written in eleven places is eleven places to change. Custom properties fix this, and asking for them changes the quality of everything the model gives you afterwards."}, {"t": "code", "lang": "css", "filename": "styles.css", "code": ":root{\n  --ink: #0d0d0d;\n  --paper: #ffffff;\n  --accent: #c6ff4a;\n  --space: 8px;\n  --radius: 24px;\n}\n\n.card{\n  background: var(--paper);\n  border-radius: var(--radius);\n  padding: calc(var(--space) * 3);\n  color: var(--ink);\n}"}, {"t": "demo", "kind": "code-explainer", "title": "Change a value, watch the design move"}, {"t": "h", "text": "JavaScript: behaviour, added last"}, {"t": "p", "text": "The useful discipline is to build the page so it makes sense without JavaScript, then add behaviour on top. Not because visitors disable it, but because a page that depends on script for its basic meaning is a page that breaks completely when one line fails."}, {"t": "code", "lang": "js", "filename": "script.js", "code": "const button = document.querySelector(''.card button'');\n\nbutton?.addEventListener(''click'', () => {\n  button.textContent = ''Reserved'';\n  button.disabled = true;\n});"}, {"t": "callout", "kind": "tip", "title": "The `?.` is not decoration", "text": "If `querySelector` finds nothing it returns `null`, and calling a method on `null` throws an error that stops every line of script after it. The `?.` says ''only if this exists''. One character, and the rest of your page keeps working."}, {"t": "prompt", "n": "04", "title": "Ask for the three layers to stay separate", "body": "Build a {COMPONENT} using plain HTML, CSS and JavaScript in three separate files.\n\nRules:\n- HTML carries meaning only. Use semantic elements. No styling attributes, no presentational class names like `red-text`.\n- All colours, spacing and radii come from CSS custom properties defined once on :root.\n- JavaScript adds behaviour only. The component must still make sense with JavaScript switched off.\n\nAfter the code, list which decisions you made that I might reasonably disagree with.", "why": {"context": "Three files, named layers — the model now has an architecture to work inside.", "constraints": "Each rule removes a specific bad habit: inline styles, magic values, script-dependent meaning.", "output": "Code plus a list of debatable choices, which turns a delivery into a conversation.", "iteration": "Argue with one item on that list. That exchange is where you learn the most."}}, {"t": "task", "title": "Take the layers apart", "steps": ["Ask Claude for a pricing card with the prompt above.", "Save the three files and open the page.", "Comment out the `<link>` to the stylesheet and reload. Can you still tell what everything is?", "Restore it, then comment out the `<script>`. Is the card still readable?", "If either answer is no, tell Claude which one and ask it to fix that specific failure."], "done": "You have tested the separation instead of trusting it. This is the fastest way to find out whether generated code is actually well built."}, {"t": "quiz", "q": "Why prefer `<button>` over a `<div>` with a click handler?", "type": "multi", "options": ["It is reachable and operable by keyboard without extra code", "Screen readers announce it as a button", "It responds to Enter and Space by default", "It renders faster"], "correct": [0, 1, 2], "why": "Focusability, the announced role and keyboard activation all come free with the correct element. Rendering speed is not the reason — accessibility and less code you have to write and maintain are."}, {"t": "summary", "points": ["HTML is meaning, CSS is appearance, JavaScript is behaviour.", "Markup should be readable with no stylesheet attached.", "Define colours and spacing once as custom properties, then reuse them.", "Add behaviour last, and make sure the page survives without it."]}]'::jsonb, 4, true, 14, null, null),
  ('8e6050cc-05cb-581d-b1ee-d8607fec7650', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'what-claude-can-and-cannot-do', 'What Claude can and cannot do', 'An honest map of the tool, so you stop being surprised by it.', '[{"t": "h", "text": "Knowing the edges is what makes it useful."}, {"t": "p", "text": "Most frustration with AI coding comes from expecting the wrong thing. Not because the tool is bad, but because nobody drew the map. So here is the map, honestly, including the parts that are inconvenient."}, {"t": "h", "text": "What it genuinely does well"}, {"t": "list", "items": ["**First drafts of anything structured.** Layouts, components, forms, config files. Minutes instead of hours.", "**Explaining code you did not write.** Line by line, at whatever level you ask for.", "**Translating between languages and frameworks.** Same idea, different syntax.", "**Finding the cause of an error you can describe.** Give it the message and the code and it is usually right.", "**Boring correctness.** Accessibility attributes, responsive breakpoints, edge cases — provided you ask."]}, {"t": "h", "text": "What it cannot do, and will not tell you it cannot"}, {"t": "list", "items": ["**Know your context.** It has never met your client and cannot see your files unless you show it.", "**Remember yesterday.** A new conversation starts empty. Every time.", "**Have taste on your behalf.** It will produce something defensible. Whether it is *right* is your call.", "**See your screen.** ''It looks wrong'' is not a description it can act on.", "**Be certain.** It can be fluent and mistaken at the same time, with no change in tone."]}, {"t": "callout", "kind": "warning", "title": "Fluent and wrong look identical", "text": "This is the failure mode to internalise. Wrong answers arrive with exactly the same confidence as right ones. There is no tell. The only defence is to check — run it, read it, test the edge case."}, {"t": "figure", "kind": "context", "caption": "What the model can see when you ask it something"}, {"t": "h", "text": "Context is the whole game"}, {"t": "p", "text": "The model''s world is what is in the current conversation. Not your repository, not last week, not the thing you meant. If you have not said it, it does not exist. This sounds limiting until you realise it is completely under your control — which makes it a skill rather than an obstacle."}, {"t": "demo", "kind": "context-compare", "title": "Same question, different amounts of context"}, {"t": "h", "text": "How to work with the uncertainty"}, {"t": "p", "text": "You do not need to verify every line. You need a habit that catches the expensive mistakes: run it before you believe it, read anything that touches data or permissions, and ask ''what would make this wrong?'' whenever an answer arrives suspiciously neatly."}, {"t": "prompt", "n": "05", "title": "Make the model argue with itself", "body": "Here is a solution you just gave me:\n\n{PASTE}\n\nNow argue against it. What are its weaknesses? Where would it break — unusual input, small screens, slow connections, someone using only a keyboard? What did you assume that I never told you?\n\nBe specific and do not soften it.", "why": {"context": "Its own output, so the critique is concrete rather than general advice.", "constraints": "Named failure categories stop the answer being a shrug about edge cases.", "output": "A list of weaknesses and — most valuable — the assumptions it silently made.", "iteration": "Every assumption it names is a decision you never made. Make it now, explicitly."}}, {"t": "task", "title": "Catch a confident mistake", "steps": ["Ask Claude for a function that validates an email address with a regular expression.", "Before running it, ask: ''What valid addresses does this reject, and what invalid ones does it accept?''", "Read the answer. It will find real problems in its own code.", "Ask why it wrote the imperfect version first."], "done": "You have seen fluent output that was not complete, and you found it by asking rather than by luck."}, {"t": "quiz", "q": "Which of these is a genuine limitation rather than a prompting problem?", "type": "single", "options": ["It produced generic output", "It forgot a constraint from earlier in the conversation", "It cannot know whether your client will like the design", "It used a library you did not want"], "correct": [2], "why": "The other three are fixable by prompting better: add constraints, restate them, exclude the library. Whether a specific person likes a specific design is information the model does not have and cannot obtain."}, {"t": "summary", "points": ["Excellent at first drafts, explanation, translation and diagnosable errors.", "Cannot know your context, remember past sessions, or hold taste for you.", "Fluent and wrong are indistinguishable — check, do not trust.", "Context is the whole game, and it is entirely yours to control."]}]'::jsonb, 5, true, 11, null, null),
  ('ec668ebf-8dd7-5a53-8a12-7e70c41b1e6a', '0117796f-d1ee-5e5a-8132-f58c5592b527', 'your-ai-development-workflow', 'Your AI development workflow', 'Thirteen steps you will use on every project for the rest of the course.', '[{"t": "h", "text": "A workflow beats a good prompt."}, {"t": "p", "text": "People chase the perfect prompt. The people who actually ship have something duller and far more effective: an order they always work in. It stops the two failures that ruin AI-assisted builds — starting to code before you know what you are building, and accepting output before you have checked it."}, {"t": "figure", "kind": "workflow", "caption": "The thirteen steps, and where each kind of prompt belongs"}, {"t": "h", "text": "The thirteen steps"}, {"t": "list", "ordered": true, "items": ["**Describe the goal.** One sentence. What must this thing do?", "**Give context.** Who is it for, what exists already, what is it part of?", "**Define constraints.** What is ruled out. This is where quality is decided.", "**Give visual direction.** Specific enough to be checkable, not ''modern and clean''.", "**Define technical requirements.** Files, dependencies, browser support, performance.", "**Ask for implementation.** Only now. Scoped to one piece.", "**Inspect the output.** Read it. Understand it. Do not skim it.", "**Test.** Run it. Resize it. Use the keyboard. Open the console.", "**Report problems.** Precisely: expected, actual, when it started.", "**Iterate.** Small, named changes. Keep what works.", "**Refactor.** Remove repetition once the shape has settled.", "**Polish.** Spacing, motion, states, the last ten per cent.", "**Ship.** Deploy, then check it again in public."]}, {"t": "callout", "kind": "note", "title": "Steps 1–5 are where the money is", "text": "Beginners start at step 6 and wonder why the result is generic. The first five steps cost ten minutes and determine everything the model produces afterwards. Skipping them does not save time; it moves the time to step 10, where it costs more."}, {"t": "h", "text": "What a real session looks like"}, {"t": "p", "text": "Not one prompt and a finished site. A conversation that narrows."}, {"t": "demo", "kind": "session", "title": "A real session, replayed"}, {"t": "p", "text": "Notice what happens there. The first exchange produces no code at all — it produces agreement about what is being built. The build then arrives in pieces small enough to judge. When something is wrong, the report is specific, so the fix is specific. Nothing gets rewritten from scratch, so nothing that worked quietly stops working."}, {"t": "h", "text": "Where it goes wrong"}, {"t": "list", "items": ["**Asking for everything at once.** You cannot review a whole site in one read, so you do not review it.", "**Vague problem reports.** ''It''s broken'' gets a guess. ''The nav overlaps the hero below 480px'' gets a fix.", "**Rewriting instead of adjusting.** Every rewrite reintroduces problems you had already solved.", "**Believing it because it compiles.** Working and correct are different words."]}, {"t": "prompt", "n": "06", "title": "Open a session properly", "body": "We are going to build {PROJECT} together over several messages. Before any code, confirm you have understood the following, and ask me about anything that is unclear or missing.\n\nGoal: {ONE SENTENCE}\nAudience: {WHO}\nOne action they should take: {ACTION}\nHard constraints: {LIST}\nVisual direction: {LIST}\nTechnical: plain HTML, CSS and JavaScript in three files, no libraries, must work from 360px up.\n\nThen propose a build order — which piece we should make first, and why.", "why": {"context": "Everything the model needs, in one place, at the start of the session.", "constraints": "Stated once here rather than repeated in every later message.", "output": "Confirmation, questions and a build order — no code until the plan is agreed.", "iteration": "Its questions are the gaps in your own thinking. Answer them properly; that is the real value of this step."}}, {"t": "task", "title": "Run the workflow once, end to end", "steps": ["Pick something genuinely small: a single contact section.", "Write out steps 1 to 5 in a text file before you open Claude.", "Send the opening prompt above and answer whatever it asks.", "Ask for the implementation. Read every line before you run it.", "Test it at 360px and with the keyboard only. Report one problem precisely.", "Iterate until it is right. Note how many messages it took."], "done": "You have completed one full loop. Every project in this course is this loop, repeated at a larger size."}, {"t": "quiz", "q": "Where do most AI-assisted builds actually go wrong?", "type": "single", "options": ["The model produces poor code", "The developer starts at step 6 and skips goal, context and constraints", "The technology is not mature enough", "There are not enough good prompt templates available"], "correct": [1], "why": "The code is usually fine for what was asked. What is missing is the five steps before the asking — which is why the same model produces mediocre work for one person and excellent work for another."}, {"t": "summary", "points": ["A repeatable order beats a clever prompt.", "Steps 1 to 5 happen before any code exists, and decide the outcome.", "Build in pieces small enough to actually review.", "Report problems precisely; adjust rather than rewrite."]}]'::jsonb, 6, true, 13, null, null),
  ('d9e8ff3b-1d9f-57f6-81e2-6533fe7e0eec', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'understanding-claude', 'Understanding Claude', 'What is actually happening when you send a message — and why that changes how you write one.', '[{"t": "h", "text": "It is completing your document."}, {"t": "p", "text": "Underneath the conversation, the model is doing one thing: reading everything in front of it and producing what most plausibly comes next. Not looking anything up. Not running your code. Reading the whole conversation as one document and continuing it."}, {"t": "p", "text": "That sounds reductive until you notice what follows from it. **Everything in the conversation shapes the answer** — your first message, its own earlier replies, the code you pasted, the tone you used. If you want a different answer, change the document."}, {"t": "figure", "kind": "context", "caption": "Everything visible to the model when it answers"}, {"t": "h", "text": "Three consequences you can act on"}, {"t": "p", "text": "**It has no memory between conversations.** Yesterday''s session is gone. Not hidden — gone. Re-establishing context at the start of a session is part of the job, not a workaround."}, {"t": "p", "text": "**Its own replies become part of the input.** If it makes a wrong assumption in message two and you do not correct it, that assumption is now context for messages three through twenty. Correct errors immediately, while they are cheap."}, {"t": "p", "text": "**Vagueness resolves to the average.** Ask for ''a modern website'' and you get the centre of everything that has ever been called modern. That is not the model failing; that is the only honest answer to an unspecific question."}, {"t": "callout", "kind": "note", "title": "Why generic output is your fault, in a useful way", "text": "This is good news. If the output is average because the input was unspecific, then specificity is a lever you control. Nothing needs to change about the tool for your results to get dramatically better."}, {"t": "h", "text": "Confidence is not a signal"}, {"t": "p", "text": "The model has no separate channel for uncertainty. A guess is written in the same voice as a fact. You cannot read confidence off the prose — which means checking is not paranoia, it is the only available method."}, {"t": "demo", "kind": "context-compare", "title": "Watch specificity change the answer"}, {"t": "prompt", "n": "01", "title": "Make it show its reasoning", "body": "Before you answer, tell me:\n1. What you understood my goal to be\n2. What you are assuming because I did not say\n3. What you would need to know to give a better answer\n\nThen answer.\n\nMy question: {QUESTION}", "why": {"context": "Forces the model''s interpretation into the open before it commits to an answer.", "constraints": "Three numbered items, in order, so it cannot skip the uncomfortable second one.", "output": "Its reading of you, its assumptions, its gaps — and only then the answer.", "iteration": "Item 2 is the gold. Every assumption listed is a decision you have not made yet."}}, {"t": "task", "title": "Find your own vagueness", "steps": ["Write a request for something you actually want to build.", "Run it through the prompt above rather than sending it directly.", "Read the assumptions it lists.", "Rewrite your original request so that at least three of those assumptions are no longer necessary."], "done": "You have watched a vague request become a specific one, and you can now feel the difference in the answers."}, {"t": "quiz", "q": "You start a new conversation and say ''continue where we left off yesterday''. What happens?", "type": "single", "options": ["It retrieves the previous conversation", "It has no access to it and will either say so or invent a plausible continuation", "It searches your project files", "It asks you to authenticate"], "correct": [1], "why": "A new conversation is empty. The second half of that answer is the dangerous part: asked to continue something it cannot see, a model may produce a fluent continuation of a conversation that never happened."}, {"t": "summary", "points": ["The model continues the document in front of it. That document is your whole conversation.", "No memory across sessions; its own replies become context within one.", "Vague input resolves to average output — which makes specificity your lever.", "Confidence carries no information about correctness."]}]'::jsonb, 1, true, 10, null, null),
  ('c1b203c6-c249-5eed-9719-7b371f5764c5', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'how-claude-interprets-instructions', 'How Claude interprets instructions', 'The gap between what you said and what you meant, and how to close it.', '[{"t": "h", "text": "It does what you said."}, {"t": "p", "text": "Almost every ''the AI got it wrong'' moment is really a gap between the instruction and the intention. The model resolved an ambiguity you did not know you had left open. Learning to spot those ambiguities before you send is most of what prompting is."}, {"t": "h", "text": "Where the gaps hide"}, {"t": "p", "text": "**Words that sound like specifications but are not.** Modern, clean, professional, nice, sleek, minimal. Each one is a compliment about a result, not an instruction about how to get there. Two people using ''minimal'' can mean opposite layouts."}, {"t": "p", "text": "**Scope you assumed was obvious.** ''Fix the header'' — only the header, or also the navigation inside it? ''Make it responsive'' — down to what width? On what device?"}, {"t": "p", "text": "**Silence about what must not change.** You ask for a colour change. You get a colour change and a restructured layout, because nothing said the layout was settled."}, {"t": "figure", "kind": "anatomy", "caption": "The four parts of an instruction that lands"}, {"t": "h", "text": "The fix: say what you mean by the word"}, {"t": "p", "text": "Do not remove ''minimal'' from your vocabulary. Define it inline. ''Minimal — meaning one accent colour, no borders, no shadows, whitespace instead of dividers.'' Now it is checkable, and you have also just clarified it for yourself."}, {"t": "code", "lang": "js", "filename": "before-and-after.txt", "code": "// vague\n\"Make the card look better and more modern.\"\n\n// specific\n\"Increase the card''s internal padding to 32px, remove the drop\n shadow, replace the 1px border with a 1px hairline in --line,\n and set the title to the h3 size from the type scale.\n Do not change the layout or the copy.\""}, {"t": "callout", "kind": "tip", "title": "Add the fence", "text": "Almost every change instruction should end with a sentence saying what must stay the same. ''Do not change the layout, the copy, or the class names.'' One line, and you stop getting helpful surprises."}, {"t": "h", "text": "Literal by default"}, {"t": "p", "text": "Ask for ''a few examples'' and you might get three, or seven. Ask for three and you get three. Numbers, file names, element names and exact values all collapse ambiguity for free — use them wherever you actually have a preference."}, {"t": "demo", "kind": "instruction-gap", "title": "Spot the ambiguity"}, {"t": "prompt", "n": "02", "title": "Have it find your ambiguities first", "body": "Here is an instruction I am about to send you:\n\n\"{YOUR INSTRUCTION}\"\n\nDo not carry it out. Instead, list every way it could reasonably be interpreted differently from what I probably meant. For each, say what extra sentence would remove the ambiguity.", "why": {"context": "Your real instruction, examined before it costs you a wrong build.", "constraints": "''Do not carry it out'' is essential or you get the work instead of the review.", "output": "A list of ambiguities with the exact sentence that closes each one.", "iteration": "Paste the improved instruction back and compare the result with what you would have got."}}, {"t": "task", "title": "Rewrite three instructions", "steps": ["Take these: ''make it look professional'', ''fix the mobile version'', ''clean up this code''.", "Rewrite each one so that a stranger could tell whether it had been done correctly.", "Send both versions of one of them in separate conversations.", "Compare the two results side by side."], "done": "You have measured the cost of a vague instruction in output quality, on your own work."}, {"t": "quiz", "q": "You ask for a colour change and get a redesigned layout as well. What was missing?", "type": "single", "options": ["A more powerful model", "A sentence saying what must not change", "More detail about the colour", "A shorter prompt"], "correct": [1], "why": "Without a fence, an unmentioned area is fair game. Naming what is settled is as important as naming what should change — and it takes one sentence."}, {"t": "summary", "points": ["Wrong output is usually an ambiguity you left open.", "Adjectives like ''modern'' and ''clean'' specify nothing until you define them inline.", "State scope: what changes, and explicitly what does not.", "Exact numbers and names remove ambiguity at no cost."]}]'::jsonb, 2, true, 11, null, null),
  ('de3d626d-cf1f-53db-89b2-409d0c4eebee', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'context', 'Context', 'The single highest-leverage thing you control.', '[{"t": "h", "text": "Context is everything."}, {"t": "p", "text": "Claude can only work with the information you give it. Not your repository, not your client meeting, not the thing you decided in the shower. If it is not in the conversation, it does not exist — and the model will fill the gap with the most average plausible thing."}, {"t": "figure", "kind": "context", "caption": "The four kinds of context, and what each one buys you"}, {"t": "h", "text": "The four kinds worth giving"}, {"t": "p", "text": "**Project context** — what you are building and who for. Changes structure and tone.\n**Technical context** — stack, files, versions, conventions. Changes the code shape.\n**Design context** — tokens, references, rules. Changes how it looks.\n**Conversational context** — what you already agreed. Changes how much you have to repeat."}, {"t": "h", "text": "More is not automatically better"}, {"t": "p", "text": "Pasting your entire codebase is not context, it is noise. The useful test for any piece of information: **would the answer be different without it?** If not, leave it out. A focused 200 words beats an unfocused 2,000."}, {"t": "demo", "kind": "context-compare", "title": "The same request at three levels of context"}, {"t": "callout", "kind": "tip", "title": "Keep a project brief", "text": "Write your goal, audience, stack, conventions and design tokens once, in a text file. Paste it at the top of any new session. Ten seconds of copying replaces ten minutes of re-explaining, and the model stops rediscovering your project every day."}, {"t": "h", "text": "Context decays as a session grows"}, {"t": "p", "text": "In a long conversation, something said early can lose against forty messages of more recent material. When a rule you set at the start starts slipping, restate it. Not as a complaint — as a line: ''Reminder: three files, no libraries, tokens only.'' It works, and it costs nothing."}, {"t": "code", "lang": "js", "filename": "project-brief.txt", "code": "PROJECT — Vlaam Bakery, one page\nAUDIENCE — locals, mostly on phones, mostly before 9am\nONE ACTION — see today''s bread and the opening hours\nSTACK — plain HTML/CSS/JS, three files, no libraries\nCONVENTIONS — BEM class names, tokens on :root, no inline styles\nTOKENS — --ink #0d0d0d  --paper #fff  --accent #c6ff4a\n          --space 8px  --radius 24px\nCONSTRAINTS — works from 360px, no stock photography,\n              readable in bright daylight on a phone"}, {"t": "prompt", "n": "03", "title": "Open with a brief", "body": "{PASTE YOUR PROJECT BRIEF}\n\nThat is the whole project. Read it back to me in three sentences so I can check you have understood it, and tell me the single most important decision that the brief does not yet answer.\n\nDo not write code yet.", "why": {"context": "The entire brief in one message, so nothing has to be inferred.", "constraints": "A read-back in three sentences forces compression, which exposes misunderstanding.", "output": "Confirmation plus the most important missing decision.", "iteration": "Answer that question, add it to the brief file, and reuse the improved brief next session."}}, {"t": "task", "title": "Write your brief", "steps": ["Create `brief.txt` and fill in the six lines from the example for a project you want to build.", "Open a session with the prompt above.", "Answer the missing decision it identifies and add the answer to the file.", "Keep the file. You will paste it at the start of every session from here on."], "done": "You have a reusable context block. This one file will save you more time than any prompt template."}, {"t": "quiz", "q": "Which piece of context would most change the answer to ''build me a hero section''?", "type": "single", "options": ["That you prefer tabs to spaces", "That the visitors are nervous first-time patients and the one action is booking", "That you are using VS Code", "That you would like it to look nice"], "correct": [1], "why": "Audience and the single action change the message, the hierarchy, the tone and the layout. Editor and indentation change nothing about the design, and ''look nice'' specifies nothing at all."}, {"t": "summary", "points": ["If it is not in the conversation, it does not exist.", "Four kinds: project, technical, design, conversational.", "Judge each addition by whether it would change the answer.", "Keep a brief file and reuse it; restate key rules in long sessions."]}]'::jsonb, 3, true, 12, null, null),
  ('540607d6-2024-5e62-a5c1-dfac3e17edee', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'writing-your-first-development-prompt', 'Writing your first development prompt', 'The six-part structure, used on something real.', '[{"t": "h", "text": "Six parts, in this order."}, {"t": "p", "text": "A development prompt that works has the same shape every time. Not a template to paste — a checklist to run through, so nothing important is left to inference."}, {"t": "figure", "kind": "anatomy", "caption": "The six parts of a development prompt"}, {"t": "list", "ordered": true, "items": ["**Goal** — what this thing must do, in one sentence.", "**Context** — who it is for, what it is part of, what already exists.", "**Constraints** — what is ruled out. Technical and creative.", "**Direction** — the specific visual or structural decisions you have already made.", "**Scope** — exactly what you want back, and what you do not.", "**Output format** — files, language, whether you want explanation with it."]}, {"t": "h", "text": "Watch it assemble"}, {"t": "p", "text": "Start with the request everyone writes, then add one part at a time and notice what each addition removes from the space of possible answers."}, {"t": "code", "lang": "js", "filename": "assembling.txt", "code": "1  Build a hero section.\n\n2  + goal\n   Build a hero section whose job is to get a visitor to book a table.\n\n3  + context\n   ...for a twelve-seat restaurant. Visitors are mostly on phones,\n   deciding between three places, in a hurry.\n\n4  + constraints\n   ...Plain HTML and CSS, no libraries, no stock photography,\n   readable at 360px, supporting line under 20 words.\n\n5  + direction\n   ...Oversized headline set tight, one accent colour, generous\n   whitespace, asymmetric, no card, no gradient.\n\n6  + scope and output\n   Return only the HTML and CSS for this section, using the tokens\n   below. Then list three decisions I might disagree with."}, {"t": "p", "text": "Line 1 could be answered ten thousand ways. Line 6 could be answered perhaps a dozen — and all dozen are things you would consider shipping. That narrowing is the entire skill."}, {"t": "demo", "kind": "prompt-builder", "title": "Build one, part by part"}, {"t": "callout", "kind": "note", "title": "You are also writing this for yourself", "text": "Half the value arrives before you press send. You cannot state the goal, the audience and the one action without deciding them — and most weak websites are weak because nobody ever did."}, {"t": "prompt", "n": "04", "title": "Your first real development prompt", "body": "GOAL — Build a hero section that gets a visitor to {ACTION}.\n\nCONTEXT — This is the first screen of a one-page site for {WHO}. Visitors are {AUDIENCE}, usually on a phone, usually deciding between options.\n\nCONSTRAINTS — Plain HTML and CSS. No libraries. No stock photography. Must be readable at 360px. Supporting line under 20 words.\n\nDIRECTION — Oversized headline set tight. One accent colour. Generous whitespace. Asymmetric composition. No card, no gradient, no shadow.\n\nTOKENS —\n{PASTE TOKENS}\n\nSCOPE — This section only. Do not build the rest of the page.\n\nOUTPUT — The HTML and the CSS, in two blocks. Then list three decisions I might reasonably disagree with.", "why": {"context": "Audience and situation are stated, so hierarchy and tone follow from something real.", "constraints": "Six exclusions, each removing a default the model would otherwise reach for.", "output": "One section, two blocks, plus a list of debatable calls — reviewable in one sitting.", "iteration": "Argue with one of the three decisions. That exchange teaches you more than the code did."}}, {"t": "task", "title": "Send it for real", "steps": ["Fill in every placeholder for a project of your own.", "Send it. Save the result as `index.html` and `styles.css`.", "Open it at 360px wide and read it as if you were the visitor.", "Pick one of the three decisions it listed and push back on it.", "Keep the improved version."], "done": "You have written a complete development prompt and had a real exchange about the result. Every build from here is this, at a larger scale."}, {"t": "quiz", "q": "Which part of the six is most often missing, and most expensive when it is?", "type": "single", "options": ["Output format", "Constraints", "Goal", "Scope"], "correct": [1], "why": "Constraints are what remove wrong answers. Without them the output is defensible but generic, and you spend the next hour discovering one by one what you did not want."}, {"t": "summary", "points": ["Goal, context, constraints, direction, scope, output — in that order.", "Each part narrows the space of possible answers.", "Scope to one piece so you can genuinely review it.", "Ask for debatable decisions and argue with one."]}]'::jsonb, 4, true, 13, null, null),
  ('439befb3-f1f5-5767-84c1-0a0a410e7c97', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'good-prompts-vs-bad-prompts', 'Good prompts vs bad prompts', 'Six real pairs, and what separates them.', '[{"t": "h", "text": "The difference is never length."}, {"t": "p", "text": "It is whether a stranger could tell if the result was correct. That is the test. Run any prompt through it and you will know immediately whether it is doing any work."}, {"t": "demo", "kind": "versus", "title": "Six pairs, side by side"}, {"t": "h", "text": "Pair one — the layout"}, {"t": "p", "text": "**Weak:** Make the page layout better.\n**Strong:** The three sections currently stack in one column at every width. Above 900px, put the image and the text side by side at 5:7, with 48px between them. Keep the stacked order on mobile."}, {"t": "p", "text": "''Better'' cannot be checked. Widths, ratios and gaps can be measured with a ruler."}, {"t": "h", "text": "Pair two — the bug"}, {"t": "p", "text": "**Weak:** The menu is broken.\n**Strong:** Tapping the menu button below 768px opens the panel, but tapping it again does not close it. Console shows no errors. It worked before I added the scroll listener in script.js line 40."}, {"t": "p", "text": "The second gives expected, actual, boundary and timing — four facts, and the cause is usually obvious from them alone."}, {"t": "h", "text": "Pair three — the style"}, {"t": "p", "text": "**Weak:** Make it feel premium.\n**Strong:** Premium here means: one accent colour used no more than twice per screen, headline tracking at -0.03em, no shadows, hairline borders in --line, and at least 96px of vertical space between sections."}, {"t": "p", "text": "Same word, defined inline. Now it is five checkable rules instead of a hope."}, {"t": "h", "text": "Pair four — the refactor"}, {"t": "p", "text": "**Weak:** Clean up this code.\n**Strong:** This file repeats the same card markup four times with different text. Extract it into one function that takes title, body and href. Do not change the rendered HTML or the class names."}, {"t": "h", "text": "Pair five — the exploration"}, {"t": "p", "text": "**Weak:** Give me some options for the hero.\n**Strong:** Give me three hero variations that differ only in composition: one centred, one left-aligned with the image right, one full-bleed with the headline overlaid. Same copy and tokens in all three."}, {"t": "h", "text": "Pair six — the review"}, {"t": "p", "text": "**Weak:** Is this good?\n**Strong:** Review this section for spacing consistency against the 8px scale, type scale adherence, contrast ratios, and keyboard operability. List findings worst-first with the reason. Do not fix anything yet."}, {"t": "callout", "kind": "tip", "title": "The stranger test", "text": "Could someone who has never met you tell whether the result satisfies the prompt? If not, the prompt is a wish. Rewrite it until the answer is yes."}, {"t": "prompt", "n": "05", "title": "Grade your own prompt", "body": "Grade this prompt out of 10 on: clarity of goal, sufficiency of context, quality of constraints, checkability of the result.\n\n\"{YOUR PROMPT}\"\n\nFor each category, say what is missing and give the exact sentence that would fix it. Then show me the rewritten prompt.", "why": {"context": "Four named categories rather than a general opinion.", "constraints": "Asking for the exact fixing sentence prevents ''be more specific'' as feedback.", "output": "Scores, gaps, fixes and a rewrite you can use immediately.", "iteration": "Run both versions and compare. You only need to do this a few times before you internalise it."}}, {"t": "task", "title": "Grade three of your own", "steps": ["Find three prompts you have actually sent this week.", "Run each through the grading prompt.", "Note which category scores lowest across all three — that is your personal weak spot.", "Write one sentence you will add to every prompt from now on to cover it."], "done": "You know your own failure pattern, which is more useful than any template."}, {"t": "quiz", "q": "Which prompt gives Claude the most useful context?", "type": "prompt", "options": ["Make a website.", "Make a modern website for my business.", "Build a responsive landing page for a premium architecture studio: 12-column grid, oversized headlines, three project rows, one call to action, no stock imagery.", "Build a website with a hero, about, services and contact section."], "correct": [2], "why": "Only the third names the subject, the structure, the visual direction and an exclusion. The fourth names sections but leaves every judgement open — organised, and still says nothing."}, {"t": "summary", "points": ["The test is checkability, not length.", "Define your adjectives inline or they specify nothing.", "For bugs: expected, actual, boundary, timing.", "For options: name the axis they should differ on."]}]'::jsonb, 5, true, 12, null, null),
  ('80efd315-a318-54be-b303-beb9dac3d7d1', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'giving-claude-constraints', 'Giving Claude constraints', 'Every constraint removes a wrong answer. That is the whole mechanism.', '[{"t": "h", "text": "Constraints are not restrictions. They are direction."}, {"t": "p", "text": "Without them, the model chooses from everything it has ever seen and lands on the middle. Each constraint you add deletes a region of that space. Enough of them and what remains is your work rather than the average of everyone''s."}, {"t": "figure", "kind": "narrowing", "caption": "What each constraint removes"}, {"t": "h", "text": "Five kinds"}, {"t": "p", "text": "**Technical** — plain HTML/CSS/JS, three files, no libraries, must work in Safari 16.\n**Structural** — one h1, semantic landmarks, no nested grids deeper than two.\n**Visual** — one accent colour, no shadows, no gradients, hairline borders only.\n**Behavioural** — works without JavaScript, keyboard operable, respects reduced motion.\n**Negative** — no cards, no carousels, no stock photography, no emoji."}, {"t": "callout", "kind": "note", "title": "Negative constraints are underrated", "text": "Saying what you do not want is often faster and more precise than describing what you do. ''No cards'' rules out a whole family of layouts in two words, and forces something more considered in their place."}, {"t": "h", "text": "Make them checkable"}, {"t": "p", "text": "A constraint you cannot verify is a preference. ''Fast'' is a preference. ''No single asset over 200KB, no layout shift on load'' is a constraint — you can open the Network panel and settle it."}, {"t": "code", "lang": "js", "filename": "constraints.txt", "code": "preference          →  constraint\n\nfast                →  no asset over 200KB, no layout shift\naccessible          →  keyboard operable, contrast 4.5:1, visible focus\nresponsive          →  no horizontal scroll from 360px to 1920px\nclean code          →  no repeated values, tokens only, no file over 300 lines\nsubtle animation    →  transform and opacity only, nothing over 600ms"}, {"t": "demo", "kind": "constraint-lab", "title": "Add constraints, watch the space shrink"}, {"t": "h", "text": "How many is too many"}, {"t": "p", "text": "Constraints that conflict produce confused output. If you ask for maximum whitespace and maximum information density, something has to give and the model will pick for you. When results start feeling compromised, look for two rules pulling in opposite directions and decide which one you actually care about."}, {"t": "prompt", "n": "06", "title": "A constraint block you can reuse", "body": "For everything in this session, these constraints apply. Confirm them once, then hold them without me repeating myself.\n\nTECHNICAL — plain HTML, CSS and JavaScript in three files. No libraries, no build step, no external requests except Google Fonts.\n\nSTRUCTURAL — semantic HTML, one h1 per page, no heading levels skipped, all interactive elements are real buttons or links.\n\nVISUAL — only the tokens I have given you. No shadows, no gradients, no rounded corners beyond --radius. One accent colour, used sparingly.\n\nBEHAVIOURAL — keyboard operable with visible focus. Contrast at least 4.5:1. Full prefers-reduced-motion path. Page is meaningful with JavaScript disabled.\n\nNEGATIVE — no card layouts, no carousels, no stock photography, no emoji, no lorem ipsum.\n\nIf a request of mine would break one of these, say so instead of quietly ignoring it.", "why": {"context": "Session-wide, so later prompts can be short.", "constraints": "All five kinds, each item checkable.", "output": "A confirmation now; compliance for the rest of the session.", "iteration": "The last line is the one that matters most — it turns silent compromises into a conversation."}}, {"t": "task", "title": "Write your own block", "steps": ["Copy the constraint block and adapt every line to how you actually want to work.", "Save it as `constraints.txt` next to your project brief.", "Use it to open your next session.", "Each time you find yourself correcting the same thing twice, add a line."], "done": "You have a reusable standard. Your prompts get shorter and your output gets better at the same time."}, {"t": "quiz", "q": "Which of these are constraints in the useful sense?", "type": "multi", "options": ["No external libraries", "Make it look premium", "No horizontal scroll from 360px upward", "Animate transform and opacity only"], "correct": [0, 2, 3], "why": "Three of them can be verified by someone who has never met you. ''Premium'' cannot be checked until you define what you mean by it — at which point it becomes several real constraints."}, {"t": "summary", "points": ["Each constraint deletes a region of possible answers.", "Five kinds: technical, structural, visual, behavioural, negative.", "If you cannot verify it, it is a preference — rewrite it.", "Keep a reusable constraint block and ask to be told when a request conflicts with it."]}]'::jsonb, 6, true, 11, null, null),
  ('72346335-c0c7-5609-a8ab-a7dbd69ea32e', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'giving-claude-design-direction', 'Giving Claude design direction', 'How to describe a look precisely enough that it can be built.', '[{"t": "h", "text": "Describe decisions, not impressions."}, {"t": "p", "text": "''Modern'', ''clean'', ''premium'', ''bold'' are reactions to a finished thing. They cannot be executed. Design direction that works names the decisions that produce the reaction — and those you can state, check and argue about."}, {"t": "h", "text": "The five axes"}, {"t": "p", "text": "**Typography** — families, scale, weights, tracking, line height, how large the largest thing is.\n**Space** — the base unit, the section rhythm, how much air around the type.\n**Colour** — how many, in what roles, how often the accent appears.\n**Composition** — grid, symmetry, alignment, where the eye lands first.\n**Motion** — what moves, how far, how fast, and what stays still."}, {"t": "figure", "kind": "axes", "caption": "Five axes — a look is a position on each"}, {"t": "p", "text": "Any style you admire can be described as a position on those five. Do that and you have a brief. Say ''modern'' and you have a mood."}, {"t": "h", "text": "Translating a reference honestly"}, {"t": "p", "text": "Naming a site you like is a shortcut that mostly fails — the model has an average impression of it at best, and you may not agree on what makes it good. Instead, look at the thing you like and write down what it is doing."}, {"t": "code", "lang": "js", "filename": "translating.txt", "code": "\"like a Swiss design annual\"\n\n→ TYPE   one grotesque, three sizes only, headline at 8vw,\n         tracking -0.04em, body at 17px / 1.6\n→ SPACE  8px base, 128px between sections, 64px gutters\n→ COLOUR paper, ink, one accent used twice per page\n→ COMP   12-column grid, hard left alignment, asymmetric,\n         generous margins, no centred text\n→ MOTION reveals under 600ms, transform and opacity only,\n         nothing loops, nothing bounces"}, {"t": "demo", "kind": "direction-lab", "title": "Move one axis at a time"}, {"t": "callout", "kind": "tip", "title": "Change one axis per iteration", "text": "If a result is not right, resist rewriting the whole direction. Move one axis — make the headline larger, or double the section spacing — and look again. You learn what each axis is worth, and you stop losing the parts that were already good."}, {"t": "h", "text": "Give tokens, not adjectives"}, {"t": "p", "text": "The strongest version of design direction is not prose at all. It is a block of custom properties plus three sentences of composition rules. The model then has your system rather than an interpretation of your mood."}, {"t": "prompt", "n": "07", "title": "Design direction that can be executed", "body": "Here is the design direction. Use it exactly; do not introduce values outside it.\n\nTYPOGRAPHY — Display: {FAMILY}, weight 500, tracking -0.03em, line-height 0.98. Body: {FAMILY}, 17px, line-height 1.6. Labels: monospace, 11px, uppercase, tracking 0.16em. Five sizes total, no others.\n\nSPACE — 8px base unit. Section padding 120px top and bottom. Container 1280px with 24px gutters.\n\nCOLOUR — {TOKENS}. The accent appears at most twice per screen. No shadows. Borders are 1px in --line only.\n\nCOMPOSITION — 12-column grid, left-aligned, asymmetric. Nothing centred except a deliberate full-screen statement. Whitespace instead of dividers.\n\nMOTION — reveals 560ms, UI transitions 280ms, one easing curve. Transform and opacity only.\n\nBuild {SECTION} to this direction. Then tell me which of these rules you found hardest to satisfy and why.", "why": {"context": "A complete system rather than a mood, so nothing has to be guessed.", "constraints": "''No values outside this'' is what stops a fourteenth grey appearing in section three.", "output": "The section, plus the friction points — which are where your system is weak.", "iteration": "Fix the system, not the section. Then rebuild and everything downstream improves."}}, {"t": "task", "title": "Translate something you like", "steps": ["Find a site whose design you admire.", "Write down its position on all five axes. Measure where you can — use the inspector.", "Turn that into a direction block like the one above.", "Build one section to it, and compare against the original."], "done": "You have converted taste into instructions. This is the skill that separates directing a model from hoping."}, {"t": "quiz", "q": "Which of these gives real design direction?", "type": "single", "options": ["Make it modern and clean", "Use a nice font and good spacing", "One grotesque, three sizes, headline at 8vw with -0.04em tracking, 128px between sections, one accent used twice per page", "Make it look like a high-end agency site"], "correct": [2], "why": "Only the third names decisions that can be executed and checked. The others describe a feeling and leave every actual choice to the model — which will resolve them into the most average version of that feeling."}, {"t": "summary", "points": ["Name decisions, not impressions.", "Five axes: typography, space, colour, composition, motion.", "Translate references by measuring them, not by naming them.", "Tokens plus three composition rules beat any amount of adjective."]}]'::jsonb, 7, true, 13, null, null),
  ('b85386df-0da0-5ee1-8c8d-e690fa32a252', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', 'working-with-existing-code', 'Working with existing code', 'The skill that matters once your project is bigger than one file.', '[{"t": "h", "text": "Fencing the change."}, {"t": "p", "text": "Building from nothing is the easy case. The real work is changing something that already exists without breaking the parts that were fine. Do that badly and every fix costs you two regressions."}, {"t": "h", "text": "Give the minimum that makes the answer correct"}, {"t": "p", "text": "Not the whole repository. Not one isolated line either. The relevant piece, plus whatever it depends on — the tokens it uses, the markup it styles, the function it calls. If you cannot decide, ask what else it needs to see before it answers."}, {"t": "code", "lang": "js", "filename": "how-to-ask.txt", "code": "Here is the component I want to change:\n{THE COMPONENT}\n\nHere are the tokens it uses:\n{TOKENS}\n\nHere is the markup it styles:\n{MARKUP}\n\nCHANGE — the card padding from 24px to 32px and the title\n         from the h4 size to the h3 size.\n\nDO NOT CHANGE — the layout, the class names, the markup\n         structure, or anything outside this component.\n\nReturn only the lines that changed, with two lines of\ncontext either side."}, {"t": "callout", "kind": "tip", "title": "Ask for a diff, not a file", "text": "''Return only the lines that changed'' is the single most useful habit in this lesson. You can review six lines properly. You cannot review a regenerated 400-line file, so you will skim it, and something will slip through."}, {"t": "h", "text": "State your conventions once"}, {"t": "p", "text": "Naming, file structure, whether you use classes or utilities, how you handle state. Say it once at the start of a session and it applies to everything after. Say it never and you will spend the session renaming things by hand."}, {"t": "demo", "kind": "diff-review", "title": "Review a change properly"}, {"t": "h", "text": "When it rewrites more than you asked"}, {"t": "p", "text": "This will happen. The response is not to accept it and tidy up afterwards — it is to say so plainly: ''That changed the layout as well. Give me only the padding and font-size change, with the layout untouched.'' Being specific about the overreach gets you a corrected diff rather than another full rewrite."}, {"t": "h", "text": "Understand before you change"}, {"t": "p", "text": "If you are about to modify code you do not understand — generated or inherited — spend one message on comprehension first. It is faster than the debugging session you are otherwise scheduling for yourself."}, {"t": "prompt", "n": "08", "title": "Understand first, then change", "body": "Here is a file I did not write:\n\n{PASTE}\n\nBefore any changes, explain it to me:\n1. What it does, in two sentences\n2. What each function is responsible for\n3. What it assumes about the rest of the project\n4. Anything here that would surprise me later\n\nDo not suggest improvements and do not change anything yet.", "why": {"context": "The actual file, so the explanation is about your code and not a generic pattern.", "constraints": "Numbered, and explicitly no changes — comprehension is the whole deliverable.", "output": "Understanding, plus the assumptions and traps you would otherwise find at the worst moment.", "iteration": "Now make your change, and you will be able to tell whether the answer is right."}}, {"t": "task", "title": "Change one thing, safely", "steps": ["Take a file from an earlier lesson that you no longer remember in detail.", "Run the comprehension prompt above and read the answer.", "Ask for one small change, with an explicit do-not-change list, and request only the changed lines.", "Apply the diff by hand. Reload and confirm nothing else moved."], "done": "You have made a surgical change to code you did not write. That is the daily reality of working on anything real."}, {"t": "quiz", "q": "What is the most reliable way to stop a small change turning into a rewrite?", "type": "single", "options": ["Paste less code", "Name what must not change, and ask for only the changed lines", "Ask for a shorter answer", "Use a more capable model"], "correct": [1], "why": "The fence plus the diff request is what does it. Pasting less removes context the model needs; asking for brevity does not stop it touching the layout."}, {"t": "summary", "points": ["Give the relevant code plus what it depends on — not everything, not one line.", "Always name what must not change.", "Ask for changed lines only, so you can actually review them.", "Understand unfamiliar code before you modify it."]}]'::jsonb, 8, true, 14, null, null),
  ('343aa850-5613-59f9-9b64-a15ad225bd8a', '4b9dbcc2-d326-51f9-913a-3d45622166bd', 'create-the-project', 'Create the project', '', '[]'::jsonb, 1, false, 12, null, null),
