  ('e582d760-ef83-5ab4-9979-5f1fcfa59992', 'd6c8b7b8-d769-54cf-9cf3-f6a1f8f59db0', 'design-prompts', 'Design prompts', '', '[]'::jsonb, 4, false, 15, null, null),
  ('c6044a09-fc2c-5478-82f4-5740a5239a68', 'd6c8b7b8-d769-54cf-9cf3-f6a1f8f59db0', 'code-prompts', 'Code prompts', '', '[]'::jsonb, 5, false, 14, null, null),
  ('df8c8cf0-256d-5925-8416-4a5f537fc43f', 'd6c8b7b8-d769-54cf-9cf3-f6a1f8f59db0', 'debugging-prompts', 'Debugging prompts', '', '[]'::jsonb, 6, false, 14, null, null),
  ('9ed100ab-6956-576a-9184-521cb4d06f1a', 'd6c8b7b8-d769-54cf-9cf3-f6a1f8f59db0', 'refactoring-prompts', 'Refactoring prompts', '', '[]'::jsonb, 7, false, 12, null, null),
