  ('3d5431b6-2567-577c-901d-541da5682860', '0a9dece4-ba97-5f92-8552-476a68ade471', 'typography', 'Typography', '', '[]'::jsonb, 3, false, 16, null, null),
  ('619ff71c-99dd-5ea8-a232-660f12eeab2d', '0a9dece4-ba97-5f92-8552-476a68ade471', 'color-systems', 'Color systems', '', '[]'::jsonb, 4, false, 14, null, null),
  ('ee47902e-4bd3-5e7f-a83a-af7ef5037b99', '0a9dece4-ba97-5f92-8552-476a68ade471', 'components', 'Components', '', '[]'::jsonb, 5, false, 15, null, null),
  ('85991377-49a3-5154-a65f-385142465af7', '0a9dece4-ba97-5f92-8552-476a68ade471', 'reusable-code', 'Reusable code', '', '[]'::jsonb, 6, false, 14, null, null),
  ('6b98df89-4cba-547c-8374-72bb710f880e', '0a9dece4-ba97-5f92-8552-476a68ade471', 'animations', 'Animations', '', '[]'::jsonb, 7, false, 16, null, null),
  ('4a9ffdbe-23bb-514e-ab13-d5dec5e847b5', '0a9dece4-ba97-5f92-8552-476a68ade471', 'micro-interactions', 'Micro-interactions', '', '[]'::jsonb, 8, false, 15, null, null),
