  ('1d19863f-027c-5107-8828-542a905f9e31', '0a9dece4-ba97-5f92-8552-476a68ade471', 'performance', 'Performance', '', '[]'::jsonb, 10, false, 17, null, null),
  ('5db960ae-9211-5dcb-b563-6e628b3d42e4', 'b879945d-7b93-55d1-b6e5-878439a89c29', 'understanding-errors', 'Understanding errors', '', '[]'::jsonb, 1, false, 13, null, null),
  ('2314838e-cbfa-59de-9542-666d4cf948c8', 'b879945d-7b93-55d1-b6e5-878439a89c29', 'console-errors', 'Console errors', '', '[]'::jsonb, 2, false, 14, null, null),
  ('71935493-ede7-5b7c-9b9b-647bd863dc1b', 'b879945d-7b93-55d1-b6e5-878439a89c29', 'broken-layouts', 'Broken layouts', '', '[]'::jsonb, 3, false, 15, null, null),
  ('f808fdcd-8932-55cf-a99d-366966b228b2', 'b879945d-7b93-55d1-b6e5-878439a89c29', 'javascript-errors', 'JavaScript errors', '', '[]'::jsonb, 4, false, 15, null, null),
  ('510f3ed2-1b0e-572f-9e05-02b8079baa96', 'b879945d-7b93-55d1-b6e5-878439a89c29', 'responsive-bugs', 'Responsive bugs', '', '[]'::jsonb, 5, false, 14, null, null),
  ('9fc0db90-ca18-5fd8-98e3-c42ff62d5f6e', 'b879945d-7b93-55d1-b6e5-878439a89c29', 'ai-debugging-prompts', 'AI debugging prompts', '', '[]'::jsonb, 6, false, 14, null, null),
  ('407cd115-2cf1-5ae4-9ca6-e9804718e566', 'b879945d-7b93-55d1-b6e5-878439a89c29', 'finding-the-root-cause', 'Finding the root cause', '', '[]'::jsonb, 7, false, 16, null, null),
