  ('0decdcc7-dcb0-55cd-a031-9349e1b5c609', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'advanced-interactions', 'Advanced interactions', '', '[]'::jsonb, 2, false, 16, null, null),
  ('89df509a-ed7d-5a30-99dc-24c59c8f0dfa', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'animations-advanced', 'Animations', '', '[]'::jsonb, 3, false, 16, null, null),
  ('40c56e81-f9e2-5516-ab6b-d481466a2fef', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'state', 'State', '', '[]'::jsonb, 4, false, 17, null, null),
  ('48e304de-146f-5970-b893-19586bdaf03e', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'forms', 'Forms', '', '[]'::jsonb, 5, false, 16, null, null),
  ('4c952ceb-0799-52f4-acb1-e77e560b2b12', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'data', 'Data', '', '[]'::jsonb, 6, false, 15, null, null),
  ('f2b25cd4-5b42-5189-a2ba-e30c0a111f73', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'api-concepts', 'API concepts', '', '[]'::jsonb, 7, false, 16, null, null),
  ('840a31b8-3b77-513e-99bc-4b6d6194b956', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'reusable-components', 'Reusable components', '', '[]'::jsonb, 8, false, 15, null, null),
  ('e32f2826-4bb5-5913-afd2-d499c3d6b5eb', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'architecture', 'Architecture', '', '[]'::jsonb, 9, false, 18, null, null),
  ('5b3b13f7-fdf1-5abb-af3f-102dd4614c08', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'testing', 'Testing', '', '[]'::jsonb, 1, false, 15, null, null),
  ('0c2c59fb-94f0-5969-9699-c7b970d26f7a', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'responsive-qa', 'Responsive QA', '', '[]'::jsonb, 2, false, 14, null, null),
  ('970f8c7f-539e-5b75-b94a-fe2e41bab90e', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'performance-final', 'Performance', '', '[]'::jsonb, 3, false, 15, null, null),
  ('acd473b1-aff9-59f3-8111-d1839febd8a5', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'seo-basics', 'SEO basics', '', '[]'::jsonb, 4, false, 13, null, null),
  ('8db86993-441c-5f58-87d3-06a7c1ecf277', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'accessibility-final', 'Accessibility', '', '[]'::jsonb, 5, false, 15, null, null),
  ('b3408d56-986f-5be4-9944-143044f32294', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'deployment', 'Deployment', '', '[]'::jsonb, 6, false, 16, null, null),
  ('6e29d944-ff5e-5dbe-ab77-1e3203dfd729', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'domains', 'Domains', '', '[]'::jsonb, 7, false, 12, null, null),
  ('ee3b5489-362d-551e-b2e7-6ac0a9340341', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'final-polish', 'Final polish', '', '[]'::jsonb, 8, false, 14, null, null)
insert into public.projects (id, level_id, slug, title, description, brief, is_final, position, published) values
  ('18d68115-d812-561b-a54e-2b81b97a20f0', '4b9dbcc2-d326-51f9-913a-3d45622166bd', 'first-landing-page', 'Build your first landing page', 'One page, one message, one call to action — built from a brief you write yourself.', '{"client": "A two-person photography studio moving from Instagram to a site of their own.", "goal": "A single page that makes someone email them.", "requirements": ["A hero with one clear message and one call to action", "A short about section written in the studio''s voice", "A grid of six work slots, drawn in CSS — no stock photography", "Working navigation, including on a phone", "Readable at 360px wide and at 1920px"], "prompts": ["project-scaffold", "hero-section", "responsive-pass"], "checklist": ["Project folder created with index.html, styles.css, script.js", "Hero written and built", "Navigation works on desktop and mobile", "Six work slots laid out on a grid", "Contact call to action reaches a real mailto or form", "Checked at 360px, 768px and 1440px", "No console errors"]}'::jsonb, false, 1, true),
  ('03d78f90-6666-5f2e-96dd-e0150d78266e', '0a9dece4-ba97-5f92-8552-476a68ade471', 'premium-brand-website', 'Build a premium brand website', 'Take the same content and raise it to studio standard: a real type scale, a real spacing system, motion that means something.', '{"client": "A small furniture maker who sells through galleries and wants to be taken seriously online.", "goal": "A site that looks like it cost money, without a photo budget.", "requirements": ["A documented design system: colour tokens, type scale, spacing scale", "At least four reusable components built from those tokens", "One considered motion system with consistent easings and durations", "Keyboard operable end to end, with visible focus states", "No layout shift on load"], "prompts": ["design-system", "component-spec", "motion-system"], "checklist": ["Tokens defined in one place and used everywhere", "Type scale applied consistently", "Four or more components reused across sections", "Motion tiers defined and applied", "Focus states visible on every interactive element", "prefers-reduced-motion path implemented", "Lighthouse accessibility pass reviewed"]}'::jsonb, false, 2, true),
  ('6bc22f1b-0081-5f30-8197-19c90f86223a', '6eb9b656-1b10-570e-9111-dd18aab1a90d', 'interactive-web-application', 'Build an interactive web application', 'Move past pages: state, data, forms and components that hold up when someone actually uses them.', '{"client": "A running club that wants members to log routes and see them on a shared board.", "goal": "An application, not a page — state that survives a refresh.", "requirements": ["A data model written down before any code", "Create, read, update and delete for one entity", "Form validation with useful error messages", "Loading, empty and error states for every view", "State that survives a page refresh"], "prompts": ["data-model", "state-management", "empty-states"], "checklist": ["Data model documented", "All four operations work", "Validation messages explain how to fix the problem", "Loading, empty and error states designed", "State restored after refresh", "No unhandled promise rejections in the console"]}'::jsonb, false, 3, true),
  ('25d69058-672b-5cb5-b60d-80a3983ab69b', '0e3df840-08ac-5805-9967-87d6016c8ea8', 'final-project', 'Final project — build your own complete website', 'A real client brief. Everything from the course, in one build, put online under your own name.', '{"client": "A fictional creative company of your choosing. Name it, give it a point of view, and write its copy yourself.", "goal": "A complete website that you would put in front of a paying client.", "requirements": ["Responsive from 360px to 1920px", "A deliberate type system, not defaults", "Working mobile navigation", "Motion that serves the content and respects reduced motion", "Interactions that actually work — no decoration pretending to be a control", "Keyboard accessible with visible focus", "Fast: no oversized assets, no layout shift", "Deployed to a live URL"], "prompts": ["project-scaffold", "design-system", "responsive-pass", "final-qa"], "checklist": ["Brief written: client, audience, one job the site must do", "Structure planned before the first prompt", "Design system defined", "All sections built", "Responsive QA at three widths", "Accessibility pass: keyboard, contrast, labels", "Performance pass: images, fonts, layout shift", "Deployed and reachable at a public URL", "Final read-through of every line of copy"]}'::jsonb, true, 4, true)
insert into public.prompts (id, slug, category, title, purpose, body, explanation, position) values
  ('0210a709-404e-59d8-8603-cc1a9ae96cf3', 'project-scaffold', 'Start', 'Start a project from nothing', 'Opens a session with enough context that the first result is worth editing.', 'I am building a one-page website for {WHO}. Their visitors are {AUDIENCE}, and the single thing the page must get them to do is {ACTION}.
insert into public.quizzes (id, level_id, lesson_id, slug, title, subtitle, passing_score, published, position) values
  ('c9d1244d-1be8-592e-8411-cb8f0642a19e', '0117796f-d1ee-5e5a-8132-f58c5592b527', null, 'foundation-assessment', 'Foundation Assessment', 'Do you know what you are building?', 70, true, 1),
  ('436247bf-97eb-5bee-a647-78ed93882f64', 'dc1a60ee-68f1-5dfe-908c-65b35b975f35', null, 'claude-fundamentals', 'Claude Fundamentals', 'Can you direct a model?', 70, true, 2),
  ('fbb41c48-07b7-5c93-8924-7f89d35b6489', 'd6c8b7b8-d769-54cf-9cf3-f6a1f8f59db0', null, 'prompt-engineering-assessment', 'Prompt Engineering Assessment', 'Nine shapes, one session.', 70, false, 3),
  ('acc5dc73-fa24-51e1-b5bd-74d8864ce395', 'b879945d-7b93-55d1-b6e5-878439a89c29', null, 'debugging-challenge', 'Debugging Challenge', 'Find the cause, not the symptom.', 70, false, 4),
  ('3182f979-88a4-5f54-b4ca-11567204e941', '0e3df840-08ac-5805-9967-87d6016c8ea8', null, 'final-assessment', 'Final Assessment', 'Everything, at once.', 70, false, 5)
insert into public.quiz_questions (id, quiz_id, question, type, explanation, points, position) values
  ('9e4df0c5-451c-5c71-9b2a-630de4b1f69f', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'A browser has downloaded index.html, styles.css and script.js. Which one decides what the page *means*?', 'single', 'HTML carries the structure and meaning — headings, paragraphs, links, buttons. CSS decides how that meaning looks, JavaScript decides how it behaves. A screen reader, a search engine and a browser with CSS disabled all still get the meaning from the HTML alone.', 1, 1),
  ('493761b7-d148-5cb1-96db-2f7879ecda91', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Which of these run on the visitor''s own device rather than on a server? Select all that apply.', 'multi', 'CSS and JavaScript execute in the visitor''s browser, which is why anything the browser can see, the visitor can see. Checking a password and storing data happen on a server precisely because they must not be under the visitor''s control.', 1, 2),
  ('1ca65de1-9fa4-5c00-8c31-b4f1fd8a055e', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'If code appears in the browser''s Sources panel, a visitor can read it.', 'tf', 'Anything the browser downloads is readable by whoever is using the browser. This is the single most useful security fact for a front-end developer: never put a secret in code the browser receives.', 1, 3),
  ('f5898046-caa0-5b0e-8087-8d7f7c15a2bc', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Claude returns a page that looks right but uses one 4MB photograph as the hero background. What is the honest description of what happened?', 'single', 'The model optimises for what you specified. Performance was not in the brief, so it was not in the output. Almost every complaint about AI-generated code is really a missing constraint.', 1, 4),
  ('00117637-fea7-5212-afdf-0a157167cfae', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'You are about to build a page for a bakery. You have one hour. What do you do first?', 'scenario', 'Every later decision — layout, hierarchy, what gets cut — resolves against the answer to that question. An hour spent building the wrong page is an hour gone; five minutes deciding what the page is for is what makes the other fifty-five useful.', 1, 5),
  ('1b8e7316-b858-5f14-8c82-d97dd7fdbb43', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Which of these is genuinely outside what Claude can do for you?', 'single', 'Taste, context about a specific person, and responsibility for the decision stay with you. That is not a limitation to work around — it is the part of the job that remains yours.', 1, 6),
  ('b25dda1d-1880-5f4b-b2be-68329512ca99', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Which steps belong in an AI development workflow *before* you ask for any code? Select all that apply.', 'multi', 'Goal, context and constraints all come before the first request. Inspecting output is step seven — it cannot happen until something exists, and it is the step people skip most often.', 1, 7),
  ('612bbe89-1d2b-58d6-afa0-e167f769c849', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'Frontend and backend is a distinction about where code runs, not about how difficult it is.', 'tf', 'Front end runs on the visitor''s device; back end runs on a machine you control. Difficulty has nothing to do with it — a front-end animation system can be far harder than a CRUD endpoint.', 1, 8),
  ('bd83fecd-697f-5ef9-af0a-9ff23431d00f', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'You ask for a landing page and get one that is technically fine but reads like every other landing page. What is the most useful next move?', 'single', 'Generic output is the average of everything the model has seen, which is exactly what you get when nothing rules anything out. Every constraint you add removes a wrong answer.', 1, 9),
  ('5c1a1e69-f662-55cd-b470-f86310bb869e', 'c9d1244d-1be8-592e-8411-cb8f0642a19e', 'What is the practical reason to read generated code rather than only running it?', 'single', 'You do not need to be able to write it from memory. You need to be able to change it on request, judge whether it is any good, and predict what a change will affect. That is the whole difference between owning a site and merely possessing one.', 1, 10),
  ('cc0d4cd6-2759-5126-abf1-e6caf7d5e3bf', '436247bf-97eb-5bee-a647-78ed93882f64', 'Which prompt gives Claude the most useful context?', 'prompt', 'Only the third names the audience, the emotional state they arrive in, the single action, and what to avoid. The fourth names structure but leaves every judgement call open — and structure without intent is how you get a page that is organised and still says nothing.', 1, 1),
  ('00eb7b5b-15e2-5477-9c05-25588395e3df', '436247bf-97eb-5bee-a647-78ed93882f64', 'What actually happens when you say ''remember what we discussed earlier'' in a fresh conversation?', 'single', 'Context is what is in the current conversation, nothing more. This is why re-establishing context at the start of a session is a skill, not a chore.', 1, 2),
  ('edf4e273-257d-5eef-919b-8b5dc6610a03', '436247bf-97eb-5bee-a647-78ed93882f64', 'Which of these are constraints, in the useful sense? Select all that apply.', 'multi', 'A constraint rules something out in a way you could check afterwards. ''Make it look nice'' rules nothing out and cannot be verified, so it changes nothing about the output.', 1, 3),
  ('4e1a7625-1deb-5149-bc43-db4c2eea5e79', '436247bf-97eb-5bee-a647-78ed93882f64', 'You paste 400 lines of your own CSS and ask for a change to one component. What should you do to get a reliable answer?', 'single', 'Working with existing code is mostly about fencing the change. Naming what must stay the same is what stops a helpful model from redesigning three things you liked.', 1, 4),
  ('8edc01e4-f730-5269-8343-d66f18c62c7d', '436247bf-97eb-5bee-a647-78ed93882f64', 'A longer prompt is always a better prompt.', 'tf', 'Length is a side effect, not the goal. A long prompt full of adjectives is still vague; a short prompt that names the audience, the action and two hard constraints is not.', 1, 5),
  ('93480080-6a08-51dd-a918-ac194fcf9b5e', '436247bf-97eb-5bee-a647-78ed93882f64', 'Which sentence gives real design direction?', 'single', 'The third names decisions a developer could act on and you could check. ''Modern and clean'' and ''like Apple'' are compliments, not instructions — and the model will resolve them into the most average version of that idea.', 1, 6),
  ('39b34af8-448a-54b5-b99c-1df5867dc8f1', '436247bf-97eb-5bee-a647-78ed93882f64', 'Claude gives you a component that works, but the class names clash with your existing system. What is the highest-value response?', 'scenario', 'Conventions are context. Stating one once and reusing it turns a series of one-off corrections into a session that stays on your rails.', 1, 7),
  ('5ed4211d-954d-58f1-b982-6e0df19cdbf4', '436247bf-97eb-5bee-a647-78ed93882f64', 'Which parts belong in a first development prompt? Select all that apply.', 'multi', 'Goal, audience and exclusions all change the output. Politeness does not — it is fine to be polite, but it is not doing any work.', 1, 8),
  ('d59efdc1-4e6c-5b4e-90e4-4d30223d3098', '436247bf-97eb-5bee-a647-78ed93882f64', 'You want three variations of a hero to choose between. What is the reliable way to ask?', 'single', 'Naming the axis — layout, tone, density — makes the variations genuinely different and comparable. ''Some options'' produces three versions of the same idea.', 1, 9),
  ('315efdff-cdaf-5b0b-876e-8d7c55706394', '436247bf-97eb-5bee-a647-78ed93882f64', 'If the first result is wrong, the fastest fix is usually to rewrite the prompt rather than to describe the problem.', 'tf', 'Describing what is wrong keeps everything that was right. Rewriting from scratch throws away the parts you had already got working, and often reintroduces problems you had already fixed.', 1, 10)
insert into public.quiz_answers (id, question_id, answer, is_correct, position) values
  ('c20613ef-c4aa-576d-8c41-4256bd726fdc', '9e4df0c5-451c-5c71-9b2a-630de4b1f69f', 'index.html', true, 1),
