  ('357c8528-0dd3-5694-bd51-9c28b8bffb68', '9e4df0c5-451c-5c71-9b2a-630de4b1f69f', 'script.js', false, 3),
  ('ec84b6f6-b39c-580b-8502-30b12a99b698', '9e4df0c5-451c-5c71-9b2a-630de4b1f69f', 'All three equally', false, 4),
  ('c7457321-5741-50cb-bcd7-090b9e207d03', '493761b7-d148-5cb1-96db-2f7879ecda91', 'Rendering your CSS', true, 1),
  ('d8dc698f-eeb3-5028-81da-ad6b49f8e711', '493761b7-d148-5cb1-96db-2f7879ecda91', 'Sending a password to be checked', false, 2),
  ('cfd5f69d-66d3-5fc2-8165-7fdeda4355c4', '493761b7-d148-5cb1-96db-2f7879ecda91', 'Running your JavaScript', true, 3),
  ('42734972-0cf5-544e-9b5e-80e72505ac39', '493761b7-d148-5cb1-96db-2f7879ecda91', 'Storing rows in a database', false, 4),
  ('b22ea31c-b5d3-53c7-957f-e2ac7a74c673', '1ca65de1-9fa4-5c00-8c31-b4f1fd8a055e', 'True', true, 1),
  ('a394c990-0231-5acf-9d33-cfb0f8a232fb', '1ca65de1-9fa4-5c00-8c31-b4f1fd8a055e', 'False', false, 2),
  ('4b1c3668-8181-580c-afb4-2762955b1160', 'f5898046-caa0-5b0e-8087-8d7f7c15a2bc', 'Claude made a mistake', false, 1),
  ('cbae7684-c7bf-5738-b0dd-8d46bbe2ade6', 'f5898046-caa0-5b0e-8087-8d7f7c15a2bc', 'Claude did what you asked, because you never mentioned performance', true, 2),
  ('bc879437-ef40-5983-b3d1-76de7f31192f', 'f5898046-caa0-5b0e-8087-8d7f7c15a2bc', 'The model is not capable of optimising images', false, 3),
  ('33320e2c-d400-5dfc-915e-30a0b77573cd', 'f5898046-caa0-5b0e-8087-8d7f7c15a2bc', 'This is unavoidable with AI-generated code', false, 4),
  ('1ea1d6e2-757e-5a18-9d59-9fde4286ae56', '00117637-fea7-5212-afdf-0a157167cfae', 'Ask Claude to build a bakery website', false, 1),
  ('0dfdf078-f59d-5bde-b7a2-4df9006311d8', '00117637-fea7-5212-afdf-0a157167cfae', 'Write down who visits the page and the one thing they should be able to do', true, 2),
  ('52106d67-785c-51bf-8a9b-3119a4fc058c', '00117637-fea7-5212-afdf-0a157167cfae', 'Choose fonts and colours', false, 3),
  ('0579a62c-c4ac-552d-a161-a4cea9fbe218', '00117637-fea7-5212-afdf-0a157167cfae', 'Set up a project folder and a build tool', false, 4),
  ('0e40380e-d264-59c4-8a9d-62593e73816a', '1b8e7316-b858-5f14-8c82-d97dd7fdbb43', 'Write a responsive navigation component', false, 1),
  ('0f9f8102-cb4a-5ca0-9e14-3acb51165e61', '1b8e7316-b858-5f14-8c82-d97dd7fdbb43', 'Explain why your layout collapses at 400px', false, 2),
  ('361c3723-14af-5d83-ac09-b3e77bd420b9', '1b8e7316-b858-5f14-8c82-d97dd7fdbb43', 'Know whether your client will like the result', true, 3),
  ('e32da723-5203-5624-aba6-f8c218348377', '1b8e7316-b858-5f14-8c82-d97dd7fdbb43', 'Refactor a 200-line file into smaller pieces', false, 4),
  ('b3747a8b-9f89-55f3-8f37-143667f00082', 'b25dda1d-1880-5f4b-b2be-68329512ca99', 'Describe the goal', true, 1),
  ('94c86ec4-b243-5e0e-8d78-74cb7d007e46', 'b25dda1d-1880-5f4b-b2be-68329512ca99', 'Give context', true, 2),
  ('4e7e0ef3-8212-5095-9d5a-3379ac93e56c', 'b25dda1d-1880-5f4b-b2be-68329512ca99', 'Define constraints', true, 3),
  ('04103725-ab7b-5069-ae59-7d8948382826', 'b25dda1d-1880-5f4b-b2be-68329512ca99', 'Inspect the output', false, 4),
  ('86a005d2-6ab6-5afd-acdf-bd5688b5fdc1', '612bbe89-1d2b-58d6-afa0-e167f769c849', 'True', true, 1),
  ('f5ace1be-dab0-5b96-aa27-c25fef16b2a2', '612bbe89-1d2b-58d6-afa0-e167f769c849', 'False', false, 2),
  ('230ae79d-93b1-53eb-b3b3-50d1db30ca23', 'bd83fecd-697f-5ef9-af0a-9ff23431d00f', 'Ask again and hope for a better result', false, 1),
  ('2c20dc61-7e31-550c-b122-8cfeb988ee1c', 'bd83fecd-697f-5ef9-af0a-9ff23431d00f', 'Rewrite it yourself from scratch', false, 2),
  ('5674bb24-5393-5c71-82ba-84f8ada30f9b', 'bd83fecd-697f-5ef9-af0a-9ff23431d00f', 'Name what is generic about it and give constraints that remove those options', true, 3),
  ('0d79a705-8690-5db4-8ba0-78bc9349614b', 'bd83fecd-697f-5ef9-af0a-9ff23431d00f', 'Switch to a different model', false, 4),
  ('ff81e047-bfab-579a-ac4e-5b77e036e570', '5c1a1e69-f662-55cd-b470-f86310bb869e', 'So you can write it yourself next time', false, 1),
  ('a6d1bd93-5d8b-5bd9-9e0a-6fb2632ad522', '5c1a1e69-f662-55cd-b470-f86310bb869e', 'So you can change it, judge it, and know what will break', true, 2),
  ('4ff9b567-9cf6-5d88-8bb0-ed2b3bb50d47', '5c1a1e69-f662-55cd-b470-f86310bb869e', 'Because reading code is faster than testing it', false, 3),
  ('f8ccbe53-6229-5536-a5da-5ab46e31cc32', '5c1a1e69-f662-55cd-b470-f86310bb869e', 'Because generated code is usually wrong', false, 4),
  ('186c1253-49af-5713-a155-fa7916229e3d', 'cc0d4cd6-2759-5126-abf1-e6caf7d5e3bf', 'Build me a website for a dentist.', false, 1),
